using System.Collections.Concurrent;
using System.Text.Json;

namespace Zenigma.Api.Games.Puzzles;

/// <summary>
/// The practice levels shipped with the app, embedded in the API too (generated by tools/generators/puzzles) so that
/// a solution can be checked against the exact level the player was given. Levels come in packs of 1000 that are loaded
/// the first time one of their levels is asked for, so the weekly growth in levels does not grow the API's memory use up front.
/// </summary>
public sealed class PracticeLevels
{
    public const int PackSize = 1000;

    private readonly Dictionary<string, int> _counts;
    private readonly ConcurrentDictionary<(string Track, int Pack), JsonElement[]> _packs = new();

    public PracticeLevels()
    {
        using var stream = typeof(PracticeLevels).Assembly.GetManifestResourceStream("levels/counts.json")
            ?? throw new InvalidOperationException("levels/counts.json is not embedded.");
        _counts = JsonSerializer.Deserialize<Dictionary<string, int>>(stream) ?? new();
        foreach (var track in PuzzleRules.Tracks)
        {
            if (!_counts.ContainsKey(track)) throw new InvalidOperationException($"levels/counts.json has no entry for {track}.");
        }
    }

    public int Count(string track) => _counts.TryGetValue(track, out var n) ? n : 0;

    /// <summary>Level numbers start at 1.</summary>
    public JsonElement? Get(string track, int level)
    {
        if (!_counts.TryGetValue(track, out var count) || level < 1 || level > count) return null;
        var pack = Pack(track, (level - 1) / PackSize);
        var index = (level - 1) % PackSize;
        return index < pack.Length ? pack[index] : null;
    }

    private JsonElement[] Pack(string track, int pack) => _packs.GetOrAdd((track, pack), key =>
    {
        using var stream = typeof(PracticeLevels).Assembly.GetManifestResourceStream($"levels/{key.Track}-{key.Pack}.json")
            ?? throw new InvalidOperationException($"levels/{key.Track}-{key.Pack}.json is not embedded.");
        using var doc = JsonDocument.Parse(stream);
        return doc.RootElement.EnumerateArray().Select(e => e.Clone()).ToArray();
    });
}
